import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem116 preserva dados operacionais',()=>{for(const [id,titulo,expected,link] of [["N6932yKNTXnAJ98cz9Eo","TUD Kit 11 Potes Vidro Herméticos Tampa Bambu 200ml a 2L Armazenamento","Kit TUD com 11 potes de vidro e tampas de bambu","https://www.mercadolivre.com.br/p/MLB41256184"],["N9EnpkbyJeTRuSriAhFn","Relógio De Parede Decorativo Deus E Bom O Tempo Todo Em Mdf","Relógio de parede Oca Decora em MDF — Deus é bom o tempo todo","https://produto.mercadolivre.com.br/MLB-6709937978-relogio-de-parede-decorativo-deus-e-bom-o-tempo-todo-em-mdf-_JM"],["NfQ2YF7qf3SL1oehasTi","Câmera Inteligente iM3 C Black Intelbras","Câmera Intelbras iM3 C Black — Wi-Fi Full HD para uso interno","https://www.mercadolivre.com.br/p/MLB18596029?pdp_filters=item_id%3AMLB4595279704"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
